 1	/* ============================================================
 2	   api-client.js — API Client module
 3	   Section 1 of the MCP Server Dashboard SPA
 4	   ============================================================ */
 5	
 6	var API = (function () {
 7	  async function request(method, path, body) {
 8	    var opts = {
 9	      method: method,
10	      headers: {},
11	    };
12	    if (body !== undefined) {
13	      opts.headers['Content-Type'] = 'application/json';
14	      opts.body = JSON.stringify(body);
15	    }
16	    var res = await fetch('/api' + path, opts);
17	    if (!res.ok) {
18	      var errData = null;
19	      try { errData = await res.json(); } catch (_) {}
20	      var errMsg = (errData && errData.error && errData.error.message) || ('HTTP ' + res.status);
21	      var errCode = (errData && errData.error && errData.error.code) || 'ERROR';
22	      throw { code: errCode, message: errMsg };
23	    }
24	    if (res.status === 204) return null;
25	    return res.json();
26	  }
27	
28	  /**
29	   * Serialize *params* as a URL query string.
30	   *
31	   * Keys whose value is `undefined` or an empty string (`''`) are silently
32	   * omitted from the output.  This is intentional: callers use `undefined` as
33	   * a "no filter" sentinel (e.g. `{ wp: wpId }` where `wpId` may be
34	   * `undefined`), and the omission prevents `?wp=undefined` from reaching
35	   * the server.
36	   *
37	   * @param {Record<string, any>|null|undefined} params - Key/value pairs to encode.
38	   * @returns {string} A `?key=value&…` string, or `''` when no params survive
39	   *   the filter.
40	   */
41	  function buildQueryString(params) {
42	    if (!params) return '';
43	    var parts = Object.keys(params)
44	      .filter(function (k) { return params[k] !== undefined && params[k] !== ''; })
45	      .map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); });
46	    return parts.length ? '?' + parts.join('&') : '';
47	  }
48	
49	  return {
50	    getProjects: function (params) {
51	      return request('GET', '/projects' + buildQueryString(params));
52	    },
53	    getProject:               function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug)); },
54	    getWorkPackages:          function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/work-packages'); },
55	    getWorkPackage:           function (repo, slug, wpId)   { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/work-packages/' + encodeURIComponent(wpId)); },
56	    deleteProject:            function (repo, slug)         { return request('DELETE', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug)); },
57	    archiveProject:           function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/archive'); },
58	    unarchiveProject:         function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/unarchive'); },
59	    getConfig:                function ()             { return request('GET',    '/config'); },
60	    updateConfig:             function (data)         { return request('PUT',    '/config', data); },
61	    getInsights:              function ()             { return request('GET',    '/insights'); },
62	    getServerInfo:            function ()             { return request('GET',    '/server-info'); },
63	    getPlanDocument:          function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/plan'); },
64	    getSynthesisDocument:     function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/synthesis'); },
65	    analyzeProjectReset:      function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/reset', { dry_run: true }); },
66	    applyProjectReset:        function (repo, slug, decisions) { return request('POST', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/reset', { dry_run: false, decisions: decisions }); },
67	    getProjectHealth:         function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/health'); },
68	    getWorkPackageOverview:   function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/work-packages/overview'); },
69	    renameProject:            function (repo, slug, title)  { return request('PATCH',  '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug), { title: title }); },
70	    renameSlug:               function (repo, slug, newSlug) { return request('PATCH',  '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug), { slug: newSlug }); },
71	    markProjectComplete:      function (repo, slug)         { return request('POST',   '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/complete'); },
72	    getRunLogs:               function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/runs'); },
73	    getRunLogEntries:         function (repo, slug, filename, afterLine) {
74	      var qs = (afterLine !== undefined && afterLine !== null) ? ('?after=' + encodeURIComponent(afterLine)) : '';
75	      return request('GET', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/runs/' + encodeURIComponent(filename) + qs);
76	    },
77	    getRunMetadata:           function (repo, slug)         { return request('GET',    '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/run-metadata'); },
78	    getDialogues: function (repo, slug, wpId) {
79	      return request('GET', '/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/dialogues' + buildQueryString({ wp: wpId }));
80	    },

